// MyChurchTeams is the resolver for the myChurchTeams field.
func (r *projectResolver) MyChurchTeams(ctx context.Context, obj *model.Project) ([]model.Team, error) {
	// Get current user ID from context
	currentUserID, ok := middleware.GetUserID(ctx)
	if !ok || currentUserID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Load current user to get their church ID
	userThunk := r.Loaders.UserByIDLoader.Load(ctx, currentUserID)
	user, err := userThunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load user: %w", err)
	}

	// Query teams filtered by project and church
	rows, err := r.DB.Queries.GetTeamsByProjectIDAndChurchID(ctx, sqlc.GetTeamsByProjectIDAndChurchIDParams{
		Projectid: obj.ID,
		Churchid:  user.ChurchID,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to load teams: %w", err)
	}

	// Convert to GraphQL models
	result := make([]model.Team, len(rows))
	for i, row := range rows {
		description := ""
		if row.Description != nil {
			description = *row.Description
		}

		result[i] = model.Team{
			ID:                  row.ID,
			ProjectID:           row.ProjectID,
			Name:                row.Name,
			Description:         description,
			JoinCode:            row.JoinCode,
			SuperTeamID:         row.SuperTeamID,
			LeaderboardExcluded: row.LeaderboardExcluded,
		}
	}

	return result, nil
}

// MyTeam is the resolver for the myTeam field.
func (r *projectResolver) MyTeam(ctx context.Context, obj *model.Project) (*model.Team, error) {
	// Get current user ID from context
	currentUserID, ok := middleware.GetUserID(ctx)
	if !ok || currentUserID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Query user's team in this project
	row, err := r.DB.Queries.GetUserTeamByProjectID(ctx, sqlc.GetUserTeamByProjectIDParams{
		Userid:    currentUserID,
		Projectid: obj.ID,
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, nil // User not in any team in this project
		}
		return nil, fmt.Errorf("failed to fetch user's team: %w", err)
	}

	// Convert to GraphQL model
	description := ""
	if row.Description != nil {
		description = *row.Description
	}

	var superTeamID *string
	if row.SuperTeamID != nil {
		superTeamID = row.SuperTeamID
	}

	return &model.Team{
		ID:          row.ID,
		ProjectID:   row.ProjectID,
		Name:        row.Name,
		Description: description,
		SuperTeamID: superTeamID,
		JoinCode:    row.JoinCode,
	}, nil
}

// Achievements is the resolver for the achievements field.
func (r *projectResolver) Achievements(ctx context.Context, obj *model.Project) ([]model.Achievement, error) {
	thunk := r.Loaders.AchievementsByProjectLoader.Load(ctx, obj.ID)
	achievements, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load achievements: %w", err)
	}

	// Apply translations to each achievement
	result := make([]model.Achievement, len(achievements))
	for i, a := range achievements {
		result[i] = r.ApplyTranslationToAchievement(ctx, a)
	}

	return result, nil
}

// Streaks is the resolver for the streaks field.
func (r *projectResolver) Streaks(ctx context.Context, obj *model.Project) ([]model.Streak, error) {
	thunk := r.Loaders.StreaksByProjectLoader.Load(ctx, obj.ID)
	streaks, err := thunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load streaks: %w", err)
	}

	result := make([]model.Streak, len(streaks))
	for i, s := range streaks {
		translated := r.ApplyTranslationToStreak(ctx, s)
		result[i] = *translated
	}

	return result, nil
}

// Journal is the resolver for the journal field.
// User-facing: returns the current user's score journal for this project
func (r *projectResolver) Journal(ctx context.Context, obj *model.Project, filter *model.ScoreJournalFilter, first *int, after *string, last *int, before *string) (*model.ScoreJournalConnection, error) {
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	return r.getScoreJournal(ctx, obj.ID, userID, filter, first, after, last, before)
}

// Project is the resolver for the project field.
func (r *queryResolver) Project(ctx context.Context, id string) (*model.Project, error) {
	// Use translation-aware wrapper to fetch project
	return r.LoadProjectWithTranslation(ctx, id)
}

// Projects is the resolver for the projects field.
func (r *queryResolver) Projects(ctx context.Context, filter *model.ProjectFilter, first *int, after *string, last *int, before *string) (*model.ProjectConnection, error) {
	// Build cache key from filter and pagination parameters
	cacheKeyParams := buildProjectCacheKeyParams(filter, first, after, last, before)
	cacheKey := cache.ProjectsFilterKey(cacheKeyParams)
	countCacheKey := cache.ProjectsCountKey(cacheKeyParams)

	// Check cache for connection result
	if cached, ok := r.Cache.Get(cacheKey); ok {
		if connection, ok := cached.(*model.ProjectConnection); ok {
			return connection, nil
		}
	}

	// Decode cursors if provided
	var afterCursor, beforeCursor *string
	if after != nil && *after != "" {
		decoded, err := pagination.DecodeCursor(*after)
		if err != nil {
			return nil, fmt.Errorf("invalid after cursor: %w", err)
		}
		afterCursor = &decoded
	}
	if before != nil && *before != "" {
		decoded, err := pagination.DecodeCursor(*before)
		if err != nil {
			return nil, fmt.Errorf("invalid before cursor: %w", err)
		}
		beforeCursor = &decoded
	}

	// Build database query parameters for cursor pagination
	params, err := buildProjectFilterParamsCursor(filter, first, afterCursor, last, beforeCursor)
	if err != nil {
		return nil, err
	}

	// Query database with cursor pagination
	rows, err := r.DB.Queries.GetProjectsFilteredCursor(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to query projects: %w", err)
	}

	// Query total count (check cache first)
	var totalCount int64
	countCached := false
	if cachedCount, ok := r.Cache.Get(countCacheKey); ok {
		if count, ok := cachedCount.(int64); ok {
			totalCount = count
			countCached = true
		}
	}

	// If not in cache, query database
	if !countCached {
		countParams := buildCountProjectsFilterParams(filter)
		totalCount, err = r.DB.Queries.CountProjectsFiltered(ctx, countParams)
		if err != nil {
			return nil, fmt.Errorf("failed to count projects: %w", err)
		}

		// Store count in cache
		r.Cache.Set(countCacheKey, totalCount)
	}

	// Determine requested limit and check if there are more results
	requestedLimit := 10 // default
	if first != nil {
		requestedLimit = *first
	} else if last != nil {
		requestedLimit = *last
	}

	hasMore := len(rows) > requestedLimit
	projects := rows
	if hasMore {
		// Trim the extra record we fetched for hasMore detection
		projects = rows[:requestedLimit]
	}

	// If backward pagination, reverse the results
	if last != nil {
		for i, j := 0, len(projects)-1; i < j; i, j = i+1, j-1 {
			projects[i], projects[j] = projects[j], projects[i]
		}
	}

	// Convert to GraphQL model
	modelProjects := make([]model.Project, len(projects))
	for i, row := range projects {
		modelProjects[i] = model.Project{
			ID:               row.ID,
			Name:             row.Name,
			Description:      row.Description,
			RulesRaw:         row.Rules,
			InfoMessageRaw:   row.InfoMessage,
			InfoMessageStart: scalars.ToDateTimePointer(row.InfoMessageStart),
			InfoMessageEnd:   scalars.ToDateTimePointer(row.InfoMessageEnd),
			StartDate:        scalars.DateTime{Time: row.StartDate.Time},
			EndDate:          scalars.DateTime{Time: row.EndDate.Time},
			Branding: &model.Branding{
				Logo: row.LogoUrl,
				Colors: &model.Colors{
					Light: &model.ColorSet{
						Accent:            row.ColorLightAccent,
						AccentContrast:    row.ColorLightAccentContrast,
						OnAccent:          row.ColorLightOnAccent,
						BackgroundDefault: row.ColorLightBackgroundDefault,
						BackgroundRaised:  row.ColorLightBackgroundRaised,
						BackgroundIndent:  row.ColorLightBackgroundIndent,
						TextDefault:       row.ColorLightTextDefault,
						TextMuted:         row.ColorLightTextMuted,
						TextHint:          row.ColorLightTextHint,
						ShadowDefault:     row.ColorLightShadowDefault,
						ShadowBlank:       row.ColorLightShadowBlank,
						BorderDefault:     row.ColorLightBorderDefault,
					},
					Dark: &model.ColorSet{
						Accent:            row.ColorDarkAccent,
						AccentContrast:    row.ColorDarkAccentContrast,
						OnAccent:          row.ColorDarkOnAccent,
						BackgroundDefault: row.ColorDarkBackgroundDefault,
						BackgroundRaised:  row.ColorDarkBackgroundRaised,
						BackgroundIndent:  row.ColorDarkBackgroundIndent,
						TextDefault:       row.ColorDarkTextDefault,
						TextMuted:         row.ColorDarkTextMuted,
						TextHint:          row.ColorDarkTextHint,
						ShadowDefault:     row.ColorDarkShadowDefault,
						ShadowBlank:       row.ColorDarkShadowBlank,
						BorderDefault:     row.ColorDarkBorderDefault,
					},
				},
				Rounding: int(row.Rounding),
			},
		}
	}

	// Build the connection
	connection := pagination.BuildProjectConnection(pagination.BuildProjectConnectionParams{
		Projects:        modelProjects,
		RequestedFirst:  first,
		RequestedLast:   last,
		RequestedAfter:  after,
		RequestedBefore: before,
		TotalCount:      int(totalCount),
		HasMore:         hasMore,
	})

	// Store connection in cache
	r.Cache.Set(cacheKey, connection)

	return connection, nil
}

// MyProjects is the resolver for the myProjects field.
func (r *queryResolver) MyProjects(ctx context.Context) ([]model.Project, error) {
	projectID, err := r.Settings.GetCurrentProjectID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get current project ID: %w", err)
	}

	// Use translation-aware wrapper to fetch project
	project, err := r.LoadProjectWithTranslation(ctx, projectID)
	if err != nil {
		return nil, fmt.Errorf("failed to load projects: %w", err)
	}

	return []model.Project{*project}, nil
}

